const snapshotMonitoringCollection = `-- name: SnapshotMonitoringCollection :one
INSERT INTO monitoring_collection_revisions(collection_id,enterprise_id,revision,integration_version,config,desired_enabled,collector_id,credential_id,credential_version,assignment_epoch,created_by)
SELECT c.id,c.enterprise_id,c.desired_revision,c.integration_version,c.config,c.desired_enabled,c.collector_id,c.credential_id,credential.version,c.assignment_epoch,$1
FROM monitoring_collections c LEFT JOIN credentials credential ON credential.id=c.credential_id AND credential.enterprise_id=c.enterprise_id
WHERE c.enterprise_id=$2 AND c.id=$3 RETURNING collection_id, enterprise_id, revision, integration_version, config, desired_enabled, collector_id, credential_id, credential_version, assignment_epoch, created_by, created_at
`

